// Digital Degrade / Glitch: Suno Studio audio effect (applied to rendered audio, not a lyric tag).
// APPROXIMATION NOTE: A true variable-bit-depth bitcrusher needs a rounding / floor / mod primitive to
// derive an integer step index at runtime. Rounding is NOT in the confirmed primitive set (g.input, g.output,
// g.zero, g.constant, g.mul, g.add, g.sub, g.div, g.abs, g.max, g.min, g.clamp, g.lerp, g.compareLt, g.dbToLin,
// g.tanh, g.biquad, g.asymmetricOnePole). Since the DSP graph is static we cannot vary the step COUNT from the
// 'crush' knob, so this is a FIXED 8-LEVEL AMPLITUDE QUANTIZER: the staircase is built as a genuine sum of 7
// g.compareLt step comparators at fixed thresholds across [-1, 1], which maps every input to one of 8 discrete
// output levels (distinct inputs in the same band collapse to the SAME output, i.e. real quantization, not an
// identity). The 'crush' knob then sets how much of that quantized signal is blended in: lower crush = more
// quantized (crush=2 is fully quantized, crush=16 is clean). This is honest amplitude quantization within the
// confirmed set; it is a fixed-depth crush, not a continuously variable bit depth. Treat as UNVERIFIED until
// tested in Suno. ASSUMPTION: g.lerp(mask, a, b) returns a when mask=0 and b when mask=1 (see AUTHORING.md).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Drive: scale by 'drive' (dB via g.dbToLin) then g.tanh for pre-crush distortion.
//   3. Amplitude quantize: clamp to [-1,1], count how many of 7 fixed thresholds the sample exceeds via
//      g.compareLt (idx in 0..7), then map idx to the center of one of 8 levels; blend by 'crush'.
//   4. Tone: g.biquad lowpass at 'tone' over the crushed signal.
//   5. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   6. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var driveDb = g.input('drive');
  var crush = g.input('crush');
  var tone = g.input('tone');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var driveLin = g.dbToLin(driveDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));

  // crush blend: lower 'crush' => more quantized. qMix = clamp((16 - crush) / 14, 0, 1).
  // crush=2 -> qMix=1 (fully quantized); crush=16 -> qMix=0 (clean pass-through).
  var qMix = g.clamp(g.div(g.sub(g.constant(16), crush), g.constant(14)), g.zero(), g.constant(1));

  // Fixed 8-level quantizer built from a sum of 7 g.compareLt step comparators at evenly spaced thresholds
  // across [-1, 1]. idx = number of thresholds strictly below x, in 0..7. level = -1 + (idx + 0.5) * (2/8).
  function staircase(x) {
    var c = g.clamp(x, g.constant(-1), g.constant(1));
    var idx = g.add(
      g.add(
        g.add(g.compareLt(g.constant(-0.75), c), g.compareLt(g.constant(-0.5), c)),
        g.add(g.compareLt(g.constant(-0.25), c), g.compareLt(g.constant(0), c))
      ),
      g.add(
        g.add(g.compareLt(g.constant(0.25), c), g.compareLt(g.constant(0.5), c)),
        g.compareLt(g.constant(0.75), c)
      )
    );
    return g.add(g.constant(-1), g.mul(g.add(idx, g.constant(0.5)), g.constant(0.25)));
  }

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var driven = g.tanh(g.mul(trimmed, driveLin));
    var quantized = staircase(driven);
    var crushed = g.lerp(qMix, driven, quantized);
    var toned = g.biquad({ input: crushed, cutoff: tone, resonance: g.constant(0.707), mode: 'lowpass' });
    var wet = g.lerp(mix, trimmed, toned);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
